    biography text,
    "playerClass" character varying(255) DEFAULT 'Novato'::character varying,
    "winsGeral" integer DEFAULT 0,
    "lossesGeral" integer DEFAULT 0,
    "winsSeason" integer DEFAULT 0,
    "lossesSeason" integer DEFAULT 0,
