    "equippedPlaymatImage" character varying(255),
    "equippedSkinId" character varying(100),
    "equippedSkinImage" character varying(255),
    "equippedDeckName" character varying(100),
    total_score numeric(10,1) DEFAULT 0,
    division character varying(50) DEFAULT 'Bronze'::character varying,
