    "passwordResetToken" character varying(255),
    "passwordResetExpiresAt" timestamp without time zone,
    "pendingNewEmail" character varying(255),
    "emailChangeToken" character varying(255),
    "emailChangeExpiresAt" timestamp without time zone,
    "adminAllowedTabs" jsonb
);


