INSERT INTO public.cards VALUES ('c249ef63-c6b4-4cf9-8223-e4845ed789b0', 'Hammer Shot', 'Destroy 1 face-up Attack Position monster with the highest ATK. (If it is a tie, you get to choose.)', '/images/cards/YGOPRO_26412047.jpg', 'Spell', 'Normal', 'DARK', 'Warrior', 4, NULL, 0, 0, 'Common', false, 3, 65, 45.00, true, '2025-12-09 21:04:09.09593', '2026-03-04 21:53:05.320169', 'Normal', 'Normal', '', false, 'YGOPRO_26412047');
INSERT INTO public.cards VALUES ('a5a5ae4d-ca8f-4b7e-b52f-cdf68fa1893a', 'Lightning Storm', 'If you control no face-up cards: Activate 1 of these effects;
● Destroy all Attack Position monsters your opponent controls.
● Destroy all Spells and Traps your opponent controls.
You can only activate 1 "Lightning Storm" per turn.', '/images/cards/YGOPRO_14532163.jpg', 'Spell', 'Normal', 'DARK', 'Warrior', 4, NULL, 0, 0, 'Common', true, 3, 43, 12.00, true, '2025-12-09 19:29:42.541536', '2026-01-26 03:07:27.383963', 'Normal', 'Normal', '', false, 'YGOPRO_14532163');
INSERT INTO public.cards VALUES ('e505dd72-16ba-4897-9e53-29f44490b6c5', 'Horn of the Unicorn', 'The equipped monster gains 700 ATK and DEF. When this card is sent from the field to the Graveyard: Return it to the top of the Deck.', '/images/cards/YGOPRO_64047146.jpg', 'Spell', 'Normal', 'DARK', 'Warrior', 4, NULL, 0, 0, 'Common', false, 3, 12, 23.00, true, '2025-12-09 20:52:48.834193', '2026-03-04 21:48:31.235927', 'Normal', 'Normal', '', false, 'YGOPRO_64047146');
INSERT INTO public.cards VALUES ('b5def168-ea9d-4b4b-a06b-fca654fa994d', 'Last Will', 'If a monster on your side of the field was sent to your Graveyard this turn, you can Special Summon 1 monster with an ATK of 1500 points or less from your Deck once during this turn. Then shuffle your Deck.', '/images/cards/YGOPRO_85602018.jpg', 'Spell', 'Normal', 'DARK', 'Warrior', 4, NULL, 0, 0, 'Common', true, 3, 12, 12.00, true, '2025-12-17 02:10:50.168134', '2026-01-26 03:07:26.375976', 'Normal', 'Normal', '', false, 'YGOPRO_85602018');
INSERT INTO public.cards VALUES ('bdea1ed9-13a4-469b-993f-4168ac7e4cdb', 'Swift Gaia the Fierce Knight', 'If this is the only card in your hand, you can Normal Summon it without Tributing.', '/images/cards/YGOPRO_16589042.jpg', 'Monster', 'Effect', 'DARK', 'Warrior', 7, NULL, 2300, 2100, 'Common', true, 3, 22, 0.00, true, '2025-12-06 06:25:51.624797', '2026-01-26 03:07:27.880147', 'Normal', 'Normal', 'Gaia The Fierce Knight', false, 'YGOPRO_16589042');
INSERT INTO public.cards VALUES ('48c6a5a4-b01d-49e1-83c4-8f786984e0c1', 'Black Luster Soldier - Envoy of the Beginning', 'Cannot be Normal Summoned/Set. Must first be Special Summoned (from your hand) by banishing 1 LIGHT and 1 DARK monster from your GY. Once per turn, you can activate 1 of these effects.
● Target 1 monster on the field; banish it. This card cannot attack the turn this effect is activated.
● If this attacking card destroys an opponent''s monster by battle: It can make a second attack in a row.', '/images/cards/YGOPRO_72989439.jpg', 'Monster', 'Effect', 'LIGHT', 'Warrior', 8, NULL, 3000, 2500, 'Common', true, 3, 34, 12.00, true, '2025-12-06 06:09:32.192847', '2026-01-26 03:07:28.048863', 'Normal', 'Normal', 'Black Luster Soldier', false, 'YGOPRO_72989439');
INSERT INTO public.cards VALUES ('77c16919-a9be-4194-898f-934bed712deb', 'Cyber-Stein', 'You can pay 5000 LP; Special Summon 1 Fusion Monster from your Extra Deck in Attack Position.', '/images/cards/YGOPRO_69015963.jpg', 'Monster', 'Effect', 'DARK', 'Machine', 2, NULL, 700, 500, 'Common', true, 3, 21, 0.00, true, '2025-12-03 04:56:24.61763', '2026-01-26 03:07:28.527757', 'Normal', 'Normal', '', false, 'YGOPRO_69015963');
INSERT INTO public.cards VALUES ('d061b72b-b628-465a-a0a8-f884e02d7eb7', 'Chaos Emperor Dragon - Envoy of the End', 'Cannot be Normal Summoned/Set. Must be Special Summoned (from your hand) by banishing 1 LIGHT and 1 DARK monster from your GY. Once per turn: You can pay 1000 LP; send as many cards in both players'' hands and on the field as possible to the GY, then inflict 300 damage to your opponent for each card sent to the opponent''s GY by this effect. You cannot activate other cards or effects during the turn you activate this card''s effect.', '/images/cards/YGOPRO_82301904.jpg', 'Monster', 'Effect', 'DARK', 'Dragon', 8, NULL, 3000, 2500, 'Common', true, 3, 21, 0.00, true, '2025-11-29 14:38:29.719182', '2026-01-26 03:07:28.590291', 'Normal', 'Normal', 'Chaos', false, 'YGOPRO_82301904');
INSERT INTO public.cards VALUES ('6a1443eb-c51b-4f66-a608-81622a94157d', 'Breaker the Magical Warrior', 'Se esta carta for Invocada Normal: Coloque 1 Contador de Feitiços nela (máx. 1). Ganha 300 de ATQ para cada Contador de Feitiços nele. Você pode remover 1 Contador de Feitiços desta carta e, em seguida, mirar 1 Feitiço/Armadilha no campo; destrua esse alvo.', '/images/cards/YGOPRO_71413901.jpg', 'Monster', 'Effect', 'DARK', 'Spellcaster', 4, NULL, 1600, 1000, 'Common', true, 3, 15, 15.00, true, '2025-11-12 01:16:41.706237', '2026-01-26 03:07:30.280876', 'Normal', 'Normal', '', false, 'YGOPRO_71413901');


