INSERT INTO public.duels VALUES ('614cef68-f3fc-4a04-ada3-8061754b5edf', 2, 1, 'Matheus', 'Admin', 'FINISHED', 8000, 8000, 1, 'MAIN2', 1040, 90, '{"deck": [{"id": "8b3ac9f6-a16d-47cb-aa1b-c00d74e8839f", "atk": 2000, "def": 1200, "name": "Axe Dragonute", "race": "Dragon", "type": "Monster", "level": 4, "cardId": "8b3ac9f6-a16d-47cb-aa1b-c00d74e8839f", "rarity": "Common", "idCarta": "AxeDragonute", "cardType": "Monster", "attribute": "DARK", "instanceId": "card_1766375443476_l67kybgq7", "description": "Se este card atacar, mude-o para a Posição de Defesa no final da Etapa de Dano."}, {"id": "733336a4-bcf0-489b-9648-792a8a26fbf6", "atk": 0, "def": 0, "name": "Change Of Heart", "race": "Warrior", "type": "Spell", "level": 4, "cardId": "733336a4-bcf0-489b-9648-792a8a26fbf6", "rarity": "Common", "idCarta": "ChangeOfHeart", "cardType": "Spell", "attribute": "DARK", "instanceId": "card_1766375443476_wffhtq3jw", "description": "Escolha 1 monstro no Campo do seu adversário e controle-o até o final do seu turno."}, {"id": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "atk": 0, "def": 0, "name": "Swords Of Revealing Light", "race": "Warrior", "type": "Spell", "level": 4, "cardId": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "rarity": "Common", "idCarta": "SwordsOfRevealingLight", "cardType": "Spell", "attribute": "DARK", "instanceId": "card_1766375443476_pi4x7y046", "description": "Depois da ativação deste card, ele permanece no campo, mas você deve destruí-lo durante a Fase Final do 3º turno do seu oponente. Quando este card for ativado: se seu oponente controlar um monstro com a face para baixo, vire com a face para cima todos os monstros que ele controla. Enquanto este card estiver com a face para cima no campo, os monstros do seu oponente não podem declarar um ataque."}, {"id": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "atk": 0, "def": 0, "name": "Drop Off", "race": "Warrior", "type": "Trap", "level": 4, "cardId": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "rarity": "Common", "idCarta": "DropOff", "cardType": "Trap", "attribute": "DARK", "instanceId": "card_1766375443476_u5y6v8j0l", "description": "Quando seu oponente realizar sua compra normal na sua Fase de Compra: seu oponente descarta 1 card que ele acabou de comprar."}, {"id": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "atk": 0, "def": 0, "name": "Swords Of Revealing Light", "race": "Warrior", "type": "Spell", "level": 4, "cardId": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "rarity": "Common", "idCarta": "SwordsOfRevealingLight", "cardType": "Spell", "attribute": "DARK", "instanceId": "card_1766375443476_ux4p1dmvr", "description": "Depois da ativação deste card, ele permanece no campo, mas você deve destruí-lo durante a Fase Final do 3º turno do seu oponente. Quando este card for ativado: se seu oponente controlar um monstro com a face para baixo, vire com a face para cima todos os monstros que ele controla. Enquanto este card estiver com a face para cima no campo, os monstros do seu oponente não podem declarar um ataque."}, {"id": "f5d62ce7-a3bb-407b-8a8c-b8ec606b6a75", "atk": 2400, "def": 1000, "name": "Thestalos The Firestorm Monarch", "race": "Pyro", "type": "Monster", "level": 6, "cardId": "f5d62ce7-a3bb-407b-8a8c-b8ec606b6a75", "rarity": "Common", "idCarta": "ThestalosTheFirestormMonarch", "cardType": "Monster", "attribute": "FIRE", "instanceId": "card_1766375443476_1pk72icqo", "description": "Se este card for Invocado por Invocação-Tributo: descarte 1 card aleatório da mão do seu oponente e, depois, se era um Card de Monstro, cause dano ao seu oponente igual ao Nível original desse monstro x 100."}, {"id": "68c88aa3-3e13-4d71-a116-8b897c943cab", "atk": 1000, "def": 700, "name": "White Magical Hat", "race": "Spellcaster", "type": "Monster", "level": 3, "cardId": "68c88aa3-3e13-4d71-a116-8b897c943cab", "rarity": "Common", "idCarta": "WhiteMagicalHat", "cardType": "Monster", "attribute": "LIGHT", "instanceId": "card_1766375443476_t1pucyyzf", "description": "Quando este card inflige dano de batalha ao seu adversário, o seu adversário descarta 1 card da sua mão aleatoriamente."}, {"id": "9369c42c-668a-44df-9553-3a0886e14e26", "atk": 2000, "def": 100, "name": "Alexandrite Dragon", "race": "Dragon", "type": "Monster", "level": 4, "cardId": "9369c42c-668a-44df-9553-3a0886e14e26", "rarity": "Common", "idCarta": "AlexandriteDragon", "cardType": "Monster", "attribute": "LIGHT", "instanceId": "card_1766375443476_y0lb26qmk", "description": "Muitas das joias perdidas dos czares podem ser encontradas nas escamas desse precioso dragão. Seu criadores continuam um mistério, assim como a forma como eles adquiriram os tesouros imperiais. Mas quem quer que encontre esse dragão terá encontrado o pote de ouro… sabendo disso ou não."}, {"id": "890d4e0a-42bf-432a-9a0c-5bdec62b82e4", "atk": 1300, "def": 800, "name": "Mataza The Zapper", "race": "Warrior", "type": "Monster", "level": 3, "cardId": "890d4e0a-42bf-432a-9a0c-5bdec62b82e4", "rarity": "Common", "idCarta": "MatazaTheZapper", "cardType": "Monster", "attribute": "DARK", "instanceId": "card_1766375443476_usqq9bf7p", "description": "Este card pode realizar um segundo ataque durante cada Fase de Batalha. O controle deste card com a face para cima no campo não pode ser trocado."}, {"id": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "atk": 2100, "def": 1600, "name": "Cyber Dragon", "race": "Machine", "type": "Monster", "level": 5, "cardId": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "rarity": "Common", "idCarta": "CyberDragon", "cardType": "Monster", "attribute": "LIGHT", "instanceId": "card_1766375443476_pv2iozl42", "description": "Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão)."}, {"id": "6d8cb833-927b-4b0b-8678-510d2a4201f5", "atk": 0, "def": 0, "name": "Confiscation", "race": "Warrior", "type": "Spell", "level": 4, "cardId": "6d8cb833-927b-4b0b-8678-510d2a4201f5", "rarity": "Common", "idCarta": "Confiscation", "cardType": "Spell", "attribute": "DARK", "instanceId": "card_1766375443476_qamc2hooh", "description": "Ative por pagar 1000 LPs. Olhe a mão do seu oponente, selecione 1 carta e descarte-a ao Cemitério."}, {"id": "68c88aa3-3e13-4d71-a116-8b897c943cab", "atk": 1000, "def": 700, "name": "White Magical Hat", "race": "Spellcaster", "type": "Monster", "level": 3, "cardId": "68c88aa3-3e13-4d71-a116-8b897c943cab", "rarity": "Common", "idCarta": "WhiteMagicalHat", "cardType": "Monster", "attribute": "LIGHT", "instanceId": "card_1766375443476_q32g043l9", "description": "Quando este card inflige dano de batalha ao seu adversário, o seu adversário descarta 1 card da sua mão aleatoriamente."}, {"id": "3ea33ff8-5475-41ac-b6dd-2b9c90343651", "atk": 1600, "def": 600, "name": "Mirage Dragon", "race": "Dragon", "type": "Monster", "level": 4, "cardId": "3ea33ff8-5475-41ac-b6dd-2b9c90343651", "rarity": "Common", "idCarta": "MirageDragon", "cardType": "Monster", "attribute": "LIGHT", "instanceId": "card_1766375443476_uh60qcdia", "description": "Seu oponente não pode ativar Cards de Armadilha durante a Fase de Batalha."}, {"id": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "atk": 0, "def": 0, "name": "Drop Off", "race": "Warrior", "type": "Trap", "level": 4, "cardId": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "rarity": "Common", "idCarta": "DropOff", "cardType": "Trap", "attribute": "DARK", "instanceId": "card_1766375443476_y34iu8b4k", "description": "Quando seu oponente realizar sua compra normal na sua Fase de Compra: seu oponente descarta 1 card que ele acabou de comprar."}, {"id": "890d4e0a-42bf-432a-9a0c-5bdec62b82e4", "atk": 1300, "def": 800, "name": "Mataza The Zapper", "race": "Warrior", "type": "Monster", "level": 3, "cardId": "890d4e0a-42bf-432a-9a0c-5bdec62b82e4", "rarity": "Common", "idCarta": "MatazaTheZapper", "cardType": "Monster", "attribute": "DARK", "instanceId": "card_1766375443476_t9ozt70i9", "description": "Este card pode realizar um segundo ataque durante cada Fase de Batalha. O controle deste card com 