INSERT INTO public.duels VALUES ('ccf66536-6936-4172-9fd3-ee99e19f976b', 1, 2, 'Admin', 'Matheus', 'FINISHED', 0, 5600, 2, 'BATTLE', 9205, 90, '{"deck": [{"id": "2ae2d581-5be3-4753-9ff5-7612108a4702", "atk": 0, "def": 0, "name": "Harpie''s Feather Duster", "type": "Spell", "level": 4, "cardId": "2ae2d581-5be3-4753-9ff5-7612108a4702", "rarity": "Common", "idCarta": "HarpiesFeatherDuster", "cardType": "Spell", "instanceId": "card_1769042308515_35yjyzx3i", "description": "Destrua todos os Cards de Magia e Armadilha que seu oponente controla."}, {"id": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "atk": 0, "def": 0, "name": "Drop Off", "type": "Trap", "level": 4, "cardId": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "rarity": "Common", "idCarta": "DropOff", "cardType": "Trap", "instanceId": "card_1769042308515_twdzuok1l", "description": "Quando seu oponente realizar sua compra normal na sua Fase de Compra: seu oponente descarta 1 card que ele acabou de comprar."}, {"id": "3ea33ff8-5475-41ac-b6dd-2b9c90343651", "atk": 1600, "def": 600, "name": "Mirage Dragon", "race": "Dragon", "type": "Monster", "level": 4, "cardId": "3ea33ff8-5475-41ac-b6dd-2b9c90343651", "rarity": "Common", "idCarta": "MirageDragon", "cardType": "Monster", "attribute": "LIGHT", "instanceId": "card_1769042308515_vaxub0wzg", "description": "Seu oponente não pode ativar Cards de Armadilha durante a Fase de Batalha."}, {"id": "d9668d3c-ad05-4dad-8b46-1768d228cdf4", "atk": 0, "def": 0, "name": "Mirror Force", "type": "Trap", "level": 4, "cardId": "d9668d3c-ad05-4dad-8b46-1768d228cdf4", "rarity": "Common", "idCarta": "MirrorForce", "cardType": "Trap", "instanceId": "card_1769042308515_7q5ftudcn", "description": "Quando um monstro do oponente declarar um ataque: destrua todos os monstros em Posição de Ataque do seu oponente."}, {"id": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "atk": 2100, "def": 1600, "name": "Cyber Dragon", "race": "Machine", "type": "Monster", "level": 5, "cardId": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e