INSERT INTO public.duels VALUES ('8728e5f8-0208-4711-848d-7a08bdb46326', 2, 1, 'Matheus', 'Admin', 'FINISHED', 7000, 8000, 1, 'MAIN1', 6595, 90, '{"deck": [{"id": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "atk": 0, "def": 0, "name": "Swords Of Revealing Light", "type": "Spell", "level": 4, "cardId": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "rarity": "Common", "idCarta": "SwordsOfRevealingLight", "cardType": "Spell", "instanceId": "card_1768270987464_9rrx074vl", "description": "Depois da ativação deste card, ele permanece no campo, mas você deve destruí-lo durante a Fase Final do 3º turno do seu oponente. Quando este card for ativado: se seu oponente controlar um monstro com a face para baixo, vire com a face para cima todos os monstros que ele controla. Enquanto este card estiver com a face para cima no campo, os monstros do seu oponente não podem declarar um ataque."}, {"id": "f5d62ce7-a3bb-407b-8a8c-b8ec606b6a75", "atk": 2400, "def": 1000, "name": "Thestalos The Firestorm Monarch", "race": "Pyro", "type": "Monster", "level": 6, "cardId": "f5d62ce7-a3bb-407b-8a8c-b8ec606b6a75", "rarity": "Common", "idCarta": "ThestalosTheFirestormMonarch", "cardType": "Monster", "attribute": "FIRE", "instanceId": "card_1768270987464_ldracux2i", "description": "Se este card for Invocado por Invocação-Tributo: descarte 1 card aleatório da mão do seu oponente e, depois, se era um Card de Monstro, cause dano ao seu oponente igual ao Nível original desse monstro x 100."}, {"id": "6a1443eb-c51b-4f66-a608-81622a94157d", "atk": 1600, "def": 1000, "name": "Breaker The magical Warrior", "race": "Spellcaster", "type": "Monster", "level": 4, "cardId": "6a1443eb-c51b-4f66-a608-81622a94157d", "rarity": "Common", "idCarta": "BreakerThemagicalWarrior", "cardType": "Monster", "attribute": "DARK", "instanceId": "card_1768270987464_0ilryweeh", "description": "Se este card for Invocado por Invocação-Normal: coloque 1 Marcador de Magia sobre ele (máx. 1). Ganha 300 de ATK para cada Marcador de Magia sobre