INSERT INTO public.duels VALUES ('7878e4e2-b7b0-4041-8a55-cadda5b7fc29', 2, 1, 'Matheus', 'Admin', 'FINISHED', 0, 7200, 2, 'BATTLE', 170, 90, '{"deck": [{"id": "890d4e0a-42bf-432a-9a0c-5bdec62b82e4", "atk": 1300, "def": 800, "name": "Mataza the Zapper", "race": "Warrior", "type": "Monster", "level": 3, "cardId": "890d4e0a-42bf-432a-9a0c-5bdec62b82e4", "rarity": "Common", "idCarta": "YGOPRO_22609617", "cardType": "Monster", "attribute": "DARK", "cardImage": "/images/cards/YGOPRO_22609617.jpg", "instanceId": "card_1772304006710_75r48hzvd", "description": "Esta carta pode fazer um segundo ataque durante cada Fase de Batalha. O controle desta placa virada para cima no campo não pode mudar."}, {"id": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "atk": 0, "def": 0, "name": "Drop Off", "type": "Trap", "level": 4, "cardId": "e3c8375e-ce79-4c47-9eb4-705c8282cc07", "rarity": "Common", "idCarta": "YGOPRO_55773067", "cardType": "Trap", "cardImage": "/images/cards/YGOPRO_55773067.jpg", "instanceId": "card_1772304006710_x076otpbu", "description": "Quando seu oponente tira para seu draw normal em sua Fase de Draw: Seu oponente descarta 1 carta que acabou de tirar."}, {"id": "6d8cb833-927b-4b0b-8678-510d2a4201f5", "atk": 0, "def": 0, "name": "Confiscation", "type": "Spell", "level": 4, "cardId": "6d8cb833-927b-4b0b-8678-510d2a4201f5", "rarity": "Common", "idCarta": "YGOPRO_17375316", "cardType": "Spell", "cardImage": "/images/cards/YGOPRO_17375316.jpg", "instanceId": "card_1772304006710_55a511ihy", "description": "Pay 1000 Life Points. Look at your opponent''s hand, select 1 card in it and discard that card."}, {"id": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "atk": 2100, "def": 1600, "name": "Cyber Dragon", "race": "Machine", "type": "Monster", "level": 5, "cardId": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "rarity": "Common", "idCarta": "YGOPRO_70095154", "cardType": "Monster", "attribute": "LIGHT", "cardImage": "/images/cards/YGOPRO_70095154.jpg", "instanceId": "card_1772304006710_z47gkk228", "description": "Se apenas seu oponente controlar um monstro, você pode Invocar Especial esta carta (da sua mão)."}, {"id": "80e01018-0efd-4db4-a585-3c00d552ea8c", "atk": 0, "def": 0, "name": "Upstart Goblin", "type": "Spell", "level": 4, "cardId": "80e01018-0efd-4db4-a585-3c00d552ea8c", "rarity": "Common", "idCarta": "YGOPRO_70368879", "cardType": "Spell", "cardImage": "/images/cards/YGOPRO_70368879.jpg", "instanceId": "card_1772304006710_91endnup0", "description": "Compre 1 carta e seu oponente ganha 1000 PV."}, {"id": "f5d62ce7-a3bb-407b-8a8c-b8ec606b6a75", "atk": 2400, "def": 1000, "name": "Thestalos the Firestorm Monarch", "race": "Pyro", "type": "Monster", "level": 6, "cardId": "f5d62ce7-a3bb-407b-8a8c-b8ec606b6a75", "rarity": "Common", "idCarta": "YGOPRO_26205777", "cardType": "Monster", "attribute": "FIRE", "cardImage": "/images/cards/YGOPRO_26205777.jpg", "instanceId": "card_1772304006710_fff88rivh", "description": "Se esta carta for Tributo Invocado: Descarte 1 carta aleatória da mão do seu oponente, então, se for uma Carta de Monstro, inflige dano ao seu oponente igual ao seu Nível x 100 original."}, {"id": "dee16bbc-fd15-4c28-9de5-26c4cbd66c6f", "atk": 0, "def": 0, "name": "Gravity Bind", "type": "Trap", "level": 4, "cardId": "dee16bbc-fd15-4c28-9de5-26c4cbd66c6f", "rarity": "Common", "idCarta": "YGOPRO_85742772", "cardType": "Trap", "cardImage": "/images/cards/YGOPRO_85742772.jpg", "instanceId": "card_1772304006710_3x8hw2p4l", "description": "Monstros de nível 4 ou superior não podem atacar."}, {"id": "ea12b6e5-8861-4970-bfe2-83904b32c6eb", "atk": 0, "def": 0, "name": "Raigeki", "type": "Spell", "level": 4, "cardId": "ea12b6e5-8861-4970-bfe2-83904b32c6eb", "rarity": "Common", "idCarta": "YGOPRO_12580477", "cardType": "Spell", "cardImage": "/images/cards/YGOPRO_12580477.jpg", "instanceId": "card_1772304006710_dikj1u2ht", "description": "Destrua todos os monstros que seu oponente controla."}, {"id": "6a1443eb-c51b-4f66-a608-81622a94157d", "atk": 1600, "def": 1000, "name": "Breaker the Magical Warrior", "race": "Spellcaster", "type": "Monster", "level": 4, "cardId": "6a1443eb-c51b-4f66-a608-81622a94157d", "rarity": "Common", "idCarta": "YGOPRO_71413901", "cardType": "Monster", "attribute": "DARK", "cardImage": "/images/cards/YGOPRO_71413901.jpg", "instanceId": "card_1772304006710_7zfxz92py", "description": "Se esta carta for Invocada Normal: Coloque 1 Contador de Feitiços nela (máx. 1). Ganha 300 de ATQ para cada Contador de Feitiços nele. Você pode remover 1 Contador de Feitiços desta carta e, em seguida, mirar 1 Feitiço/Armadilha no campo; destrua esse alvo."}, {"id": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "atk": 0, "def": 0, "name": "Swords of Revealing Light", "type": "Spell", "level": 4, "cardId": "1113f8df-6352-413d-99c1-fa2cce00c4c0", "rarity": "Common", "idCarta": "YGOPRO_72302403", "cardType": "Spell", "cardImage": "/images/cards/YGOPRO_72302403.jpg", "instanceId": "card_1772304006710_xno214z6d", "description": "Após a ativação desta carta, ela permanece no campo, mas você deve destruí-la durante a Fase Final do 3º turno do seu oponente. Quando esta carta é ativada: Se o seu oponente controlar um monstro virado para baixo, vire todos os monstros que ele controla virados para cima. Enquanto esta carta estiver virada para cima no campo, os monstros do seu oponente não podem declarar um ataque."}, {"id": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "atk": 2100, "def": 1600, "name": "Cyber Dragon", "race": "Machine", "type": "Monster", "level": 5, "cardId": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "rarity": "Common", "idCarta": "YGOPRO_70095154", "cardType": "Monster", "attribute": "LIGHT", "cardImage": "/images/cards/YGOPRO_70095154.jpg", "instanceId": "card_1772304006710_ia6rk49h7", "description": "Se apenas seu oponente controlar um monstro, você pode Invocar Especial esta carta (da sua mão)."}, {"id": "e227ea34-d3f1-4798-a9dc-eaaf83bb5e15", "atk": 2100, "def": 1600, "name": "Cyber Dragon", "race": "Machine",